import{_ as e,o,c as t,aA as r}from"./chunks/framework.Dl8a02nG.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"demos/overviews/fieldtrip_import.md","filePath":"demos/overviews/fieldtrip_import.md","lastUpdated":null}'),i={name:"demos/overviews/fieldtrip_import.md"};function d(p,a,l,s,n,c){return o(),t("div",null,[...a[0]||(a[0]=[r('<p>This demo demonstrates importing FieldTrip <code>.mat</code> files into EegFun.jl. FieldTrip is a MATLAB toolbox for EEG/MEG analysis, and its structures are a common way to exchange processed data.</p><h3 id="About-FieldTrip-.mat-Format" tabindex="-1">About FieldTrip .mat Format <a class="header-anchor" href="#About-FieldTrip-.mat-Format" aria-label="Permalink to &quot;About FieldTrip .mat Format {#About-FieldTrip-.mat-Format}&quot;">​</a></h3><p>FieldTrip stores data in MATLAB structures (generic <code>.mat</code> files). EegFun.jl uses <code>MAT.jl</code> to parse them and map them onto EegFun types.</p><p><strong>Key features</strong>:</p><ul><li>Supports raw, epoched, and averaged (timelock) data</li></ul><h3 id="Import-Capabilities" tabindex="-1">Import Capabilities <a class="header-anchor" href="#Import-Capabilities" aria-label="Permalink to &quot;Import Capabilities {#Import-Capabilities}&quot;">​</a></h3><p><strong>Data loading</strong>:</p><ul><li><p>Import of continuous <code>raw</code> data</p></li><li><p>Import of segmented <code>epochs</code> data</p></li><li><p>Import of averaged <code>timelock</code> (ERP) data</p></li></ul><h3 id="Data-Mapping" tabindex="-1">Data Mapping <a class="header-anchor" href="#Data-Mapping" aria-label="Permalink to &quot;Data Mapping {#Data-Mapping}&quot;">​</a></h3><p><strong>EegFun.read_fieldtrip</strong> maps MATLAB structures to EegFun:</p><ul><li><p>FieldTrip <code>raw</code> / <code>epochs</code> → <code>ContinuousData</code> / <code>EpochedData</code></p></li><li><p>FieldTrip <code>timelock</code> → <code>ERPData</code></p></li><li><p>Sample rates and time axes are automatically reconstructed</p></li></ul><h2 id="Workflow-Summary" tabindex="-1">Workflow Summary <a class="header-anchor" href="#Workflow-Summary" aria-label="Permalink to &quot;Workflow Summary {#Workflow-Summary}&quot;">​</a></h2><ol><li><p><strong>Load Layout</strong>: Load a layout file and prepare it for plotting.</p></li><li><p><strong>Import Data</strong>: Use <code>read_fieldtrip()</code> providing the path and the layout.</p></li><li><p><strong>Validation</strong>: Visualize the imported structures using <code>plot_databrowser()</code> for continuous/epoched data or <code>plot_erp()</code> for averaged data.</p></li></ol>',13)])])}const h=e(i,[["render",d]]);export{u as __pageData,h as default};
